import { Effect } from "effect"

interface ReminderRequest {
  readonly invoiceNumber: string
  readonly recipientEmail: string
  readonly overdueDays: number
}

interface ReminderMessage {
  readonly to: string
  readonly subject: string
  readonly body: string
}

export const prepareReminder = (request: ReminderRequest) =>
  Effect.sync((): ReminderMessage => {
    const { invoiceNumber } = request
    const { recipientEmail, overdueDays } = request
    const subject = `Payment reminder for invoice ${invoiceNumber}`
    const body = [
      `Invoice ${invoiceNumber} is ${overdueDays} days overdue.`,
      `Please include ${invoiceNumber} as your payment reference.`,
      "Contact billing if you have already sent payment."
    ].join("\n\n")

    return {
      to: recipientEmail,
      subject,
      body
    }
  })
